/* nbh-learn-units-g.js (v26.01): written units of the Learning page, section G (Ethics), units g1 to g3.
   The shape of a unit is described in nbh-learn-units.js. The people in every example are invented.
   The RBT Ethics Code (2.0) of the Behavior Analyst Certification Board is described here in the workstation's own
   words and cited by standard number; the code itself, at bacb.com, is the authority and is to be read in full. */
window.NBH_LEARN_UNITS = window.NBH_LEARN_UNITS || {};
Object.assign(window.NBH_LEARN_UNITS, {
  g1: {
    aim: [
      'Name the four core principles on which the RBT Ethics Code rests, and give an example of each in daily work.',
      'Describe how the code is organized, whom it binds and how it relates to the law and to workplace policy.',
      'Work through an ethical problem in order: notice, name, ask, act, document.',
      'Say what to do when you suspect that someone else has broken the code.'
    ],
    lesson: [
      { h: 'Why a code',
        p: ['The people you serve are often children, often cannot report what happens to them, and spend long hours alone with you. Their families let you into their homes and their lives. That is a position of trust and of power, and it is why the profession has written rules and not only good intentions.',
            'The RBT Ethics Code of the Behavior Analyst Certification Board (BACB) is that set of rules for technicians. You agree to follow it when you apply, it applies in every setting and by every means of contact, and not knowing a standard is not accepted as a reason for breaking it.'],
        check: { q: 'A technician breaks a standard and says, “Nobody told me about that one.” Under the code, this is:',
          opts: ['A full excuse.', 'An excuse for the first time only.', 'Not an excuse: technicians are responsible for knowing the code.', 'The supervisor’s fault alone.'],
          a: 2, why: 'The code says plainly that lack of awareness or misunderstanding does not excuse a failure to comply.' } },
      { h: 'Benefit others',
        p: ['The first principle: the work exists for the good of the person served. In practice it means protecting their welfare and rights before anyone’s convenience, doing no harm, putting their interests ahead of your own, and thinking about the long-term effect of what you do as well as the next five minutes.',
            'You see it in small choices. Running the teaching procedure that helps, though free play would be easier. Reporting a safety concern, though it will be awkward. Declining a side arrangement with a family that would pay well and cloud your judgment.'],
        check: { q: 'Which choice shows “benefit others”?',
          opts: ['Shortening sessions when the student is hard work.', 'Skipping data collection on a busy day.', 'Agreeing with whatever the parent says, to keep the peace.', 'Reporting to your supervisor that a procedure seems to be distressing the student.'],
          a: 3, why: 'The student’s welfare comes first, and the supervisor is the route to changing a plan.' } },
      { h: 'Compassion, dignity and respect',
        p: ['The second principle: treat every person as a person. Speak to the student, not over their head. Protect privacy during toileting, dressing and hard moments. Offer choices wherever there are choices. Attend to assent: a student who pulls away or says no is telling you something that goes to your supervisor.',
            'It also covers fairness: equal care and courtesy for every student and family, whatever their background, income, language, religion or way of living; and no ridicule, in or out of earshot. Staff-room jokes about a student are a failure of this principle even if the student never hears them.'],
        check: { q: 'Which is a failure of dignity?',
          opts: ['Asking a student which task he would like first.', 'Describing a student’s toileting accident to colleagues as a funny story.', 'Closing the door while helping a student change.', 'Greeting a student by name.'],
          a: 1, why: 'A private and embarrassing event was turned into entertainment.' } },
      { h: 'Integrity',
        p: ['The third principle: be honest and reliable, and be accountable for what you do. Record the data that happened. Write the times you worked. Keep your commitments, and say early when you cannot. Own a mistake at once.',
            'Integrity also means not leading others into dishonesty, and not going along with it: a request to change a record, to bill for time not worked, or to keep something from a supervisor is refused and reported.'],
        check: { q: 'You missed three trials of data while handling an interruption. Integrity means you:',
          opts: ['Leave the three blank, note why, and tell your supervisor if it keeps happening.', 'Fill them in with your best guess.', 'Copy the last three from yesterday.', 'Mark all three correct, since he usually is.'],
          a: 0, why: 'Data are a record of what was observed. A guess entered as data is a false record.' } },
      { h: 'Ensuring your own competence',
        p: ['The fourth principle: do only what you have been trained and checked to do, and keep learning. A technician serves only after a supervisor has confirmed competence, and the two of you keep evaluating it.',
            'Asked to run a procedure, use a device or work with a kind of need that is new to you, you say so at once and document that you did. Competence also has a personal side: tiredness, illness or trouble at home can make you less able to do the work safely, and noticing that and acting on it is part of the principle.'],
        check: { q: 'You are sent to cover a student who uses a communication device you have never seen. You:',
          opts: ['Work it out as you go.', 'Leave the device in his bag for today.', 'Tell your supervisor before the session that you have not been trained on it, and note that you did.', 'Ask the student to show you.'],
          a: 2, why: 'Unfamiliar procedures and populations need training first. The code asks you to inform the supervisor immediately and document it.' } },
      { h: 'How the code is laid out',
        p: ['After its introduction, the code has three sections. Section 1, general responsibilities: honesty, professional conduct, your role, competence, cultural responsiveness, no harassment or discrimination, personal challenges, multiple relationships, gifts, romantic relationships. Section 2, providing services: doing no harm, following direction and documenting accurately, restrictive procedures, questions and concerns, clients’ rights, confidentiality. Section 3, responsibilities to the BACB and to your supervisor: complying with requirements, honesty with both, examination integrity, self-reporting, keeping your account current.',
            'Read the code itself, in full, more than once. It is six pages. The units that follow take its parts in turn.'],
        key: ['Section 1: general responsibilities', 'Section 2: providing behavior-technician services', 'Section 3: responsibilities to the BACB and the supervisor'],
        check: { q: 'In which section of the code would you look for the standards on confidentiality?',
          opts: ['Section 1, general responsibilities.', 'Section 2, providing behavior-technician services.', 'Section 3, responsibilities to the BACB and supervisor.', 'The glossary.'],
          a: 1, why: 'Confidentiality belongs with the delivery of services.' } },
      { h: 'The code, the law and your workplace',
        p: ['Three sets of rules apply to you at once: the law, your employer’s policies, and the code. Mostly they agree. Where one is stricter, follow the stricter one: if your workplace allows no gifts at all, the code’s small allowance does not help you.',
            'When rules seem to pull apart, or a situation is covered by none of them, do not settle it alone. The code tells you to seek support from your supervisor and others at your workplace, and in the meantime to put two things first: following the law, and the interests of the client.'],
        check: { q: 'Your employer’s policy is stricter than the code on some point. You follow:',
          opts: ['The code, since it is national.', 'Whichever you prefer.', 'Neither until they agree.', 'The employer’s stricter policy.'],
          a: 3, why: 'The code sets a floor. A stricter law or policy stands above it.' } },
      { h: 'When you think something is wrong',
        p: ['A workable order for any ethical concern. Notice: something feels off, or a rule may be in play. Name it: what exactly happened, who is affected, which principle or standard it touches. Ask: take it to your supervisor promptly. Act: do what is agreed, and protect the student meanwhile. Document: what you saw, whom you told, when, and what was done.',
            'If the concern is about another person’s conduct, the code gives the same order: raise it with your supervisor first, and keep a record of every step. If it cannot be resolved that way, it goes to the appropriate authority: an employer, a licensing board, the police where there is a crime. If it is a breach of the BACB’s codes and remains unresolved with your supervisor’s support, it is reported to the BACB.',
            'If the concern is about your supervisor, your workplace names who is next. A risk of harm to a client does not wait for any of this: you act to protect the client at once.'],
        check: { q: 'You see a colleague record data for a session you know she did not run. The first step the code gives is to:',
          opts: ['Post about it anonymously.', 'Confront her in front of the family.', 'Bring it to your supervisor, and write down what you saw and when.', 'Wait to see whether she does it again.'],
          a: 2, why: 'The supervisor first, with documentation. Further reporting follows if that does not resolve it.' } }
    ],
    examples: {
      ask: 'Which core principle is most at stake?',
      intro: 'Ten moments. In each, more than one principle is present, as usually happens; choose the one that is most at stake.',
      opts: ['Benefit others', 'Compassion, dignity and respect', 'Integrity', 'Ensuring your own competence'],
      items: [
        { s: 'A technician writes that a 60-minute session took place when it lasted 40.', a: 2, why: 'A false record: honesty.' },
        { s: 'Two aides talk about a student’s “disgusting” eating habits while he sits next to them.', a: 1, why: 'He is spoken about as if he were not there, and with contempt.' },
        { s: 'A technician is asked to run a feeding procedure after watching it once on video, and agrees.', a: 3, why: 'Practicing without training or a competence check.' },
        { s: 'A technician lets a student watch videos all session because teaching brings crying.', a: 0, why: 'The technician’s comfort is put before what helps the student.' },
        { s: 'A technician changes a student in a corridor because the bathroom is far.', a: 1, why: 'Privacy during personal care.' },
        { s: 'A technician notices she has been dozing in sessions after weeks of night shifts at a second job, and says nothing.', a: 3, why: 'Her condition is affecting her ability to serve safely, and she has not acted on it.' },
        { s: 'A technician tells a parent, “Yes, I’m basically a behavior analyst.”', a: 2, why: 'A false statement about qualifications.' },
        { s: 'A technician sees a bruise and a frightened reaction and decides not to “make trouble”.', a: 0, why: 'The student’s safety is put after the technician’s ease. It is also a legal duty.' },
        { s: 'A technician mimics a student’s speech to make colleagues laugh.', a: 1, why: 'Ridicule.' },
        { s: 'A technician realizes he recorded yesterday’s data on the wrong student’s sheet, and reports it at once.', a: 2, why: 'Integrity kept: the error is owned and corrected.' }
      ]
    },
    practice: {
      title: 'One problem, in order',
      intro: 'Follow one concern from the moment you notice it. Yara is a simulated student; every adult is invented.',
      steps: [
        { t: 'Notice', see: 'For the third time this month the classroom aide, a friend of yours, has taken Yara’s snack away “until she behaves”. The plan does not include taking food away.', opts: ['Decide it is not your business.', 'Recognize that this may be a problem and should not be left.', 'Do the same, for consistency.'], a: 1, why: 'Noticing, and not explaining it away, is the first step.' },
        { t: 'Name it', see: 'What is the concern, stated plainly?', opts: ['“The aide is a bad person.”', '“On three dates, food was withheld as a consequence; this is not in the plan and may infringe Yara’s rights.”', '“Yara is not behaving.”'], a: 1, why: 'Facts, dates, and the reason it matters. No judgment of character.' },
        { t: 'Principles', see: 'Which principle is most directly involved?', opts: ['Benefit others, and dignity: a restrictive consequence outside the plan.', 'Competence only.', 'None: it is a matter of classroom style.'], a: 0, why: 'A student’s welfare and rights are at stake.' },
        { t: 'Friendship', see: 'The aide says, “Please don’t mention it. I had a hard week.”', opts: ['Agree: she is your friend.', 'Say that you understand it was a hard week, and that you have to raise it with your supervisor.', 'Report it and tell her you did not.'], a: 1, why: 'Kind, honest, and clear that the student’s interest comes first.' },
        { t: 'Ask', see: 'Whom do you tell, and when?', opts: ['Yara’s parents, tonight.', 'Your supervisor, today.', 'The other aides, at lunch.'], a: 1, why: 'The supervisor first, promptly. The supervisor decides how the school and the family are involved.' },
        { t: 'Act', see: 'Your supervisor thanks you and says she will speak with the teacher. Tomorrow you are in the room at snack time.', opts: ['Take over snack yourself and tell the aide she is banned from it.', 'Carry out the plan as written, and tell your supervisor what you see.', 'Stay away from snack so that you see nothing.'], a: 1, why: 'You do your own part correctly and keep the supervisor informed. Directing the aide is not your role.' },
        { t: 'Document', see: 'What do you write, and where?', opts: ['Nothing: it has been handled.', 'A private note on your phone about the aide’s character.', 'The dates and what you observed, whom you told and when, and what was decided, where your workplace keeps such records.'], a: 2, why: 'The code asks for documentation of the actions taken, with dates, parties and outcome.' },
        { t: 'If nothing changes', see: 'Two weeks later it happens again, and your supervisor has not acted.', opts: ['Give up.', 'Raise it again with your supervisor, and then with the next person your workplace names; if it remains unresolved, the appropriate authority.', 'Tell Yara’s parents to complain.'], a: 1, why: 'The duty does not end with one report. The chain of command, then the appropriate authority.' }
      ]
    },
    quiz: { pass: 80, draw: 10, items: [
      { q: 'How many core principles underlie the RBT Ethics Code?', opts: ['Two', 'Three', 'Four', 'Ten'], a: 2, why: 'Benefit others; compassion, dignity and respect; integrity; competence.' },
      { q: 'Which is one of the core principles?', opts: ['Behave with integrity.', 'Maximize billable hours.', 'Keep families satisfied.', 'Avoid all risk.'], a: 0, why: 'Integrity is the third principle.' },
      { q: 'The code applies:', opts: ['Only in clinics.', 'Across settings and means of contact, in all behavior-technician activities.', 'Only during paid hours on site.', 'Only when a supervisor is present.'], a: 1, why: 'Home, school, community; in person, by phone, by message.' },
      { q: 'Not knowing a standard:', opts: ['Excuses a first breach.', 'Excuses any breach.', 'Is the supervisor’s problem.', 'Does not excuse a breach.'], a: 3, why: 'The code says so directly.' },
      { q: 'Protecting a student’s privacy during personal care is an example of:', opts: ['Integrity.', 'Compassion, dignity and respect.', 'Competence.', 'Billing accuracy.'], a: 1, why: 'Dignity in daily care.' },
      { q: 'Recording only what you observed is an example of:', opts: ['Integrity.', 'Benefit others only.', 'Competence only.', 'Courtesy.'], a: 0, why: 'Honesty in documentation.' },
      { q: 'Telling your supervisor you have not been trained on a procedure is an example of:', opts: ['Disloyalty.', 'Weakness.', 'Ensuring your own competence.', 'A multiple relationship.'], a: 2, why: 'The fourth principle in action.' },
      { q: 'Where the employer’s policy is stricter than the code, you follow:', opts: ['The code.', 'Your own judgment.', 'The more lenient one.', 'The stricter policy.'], a: 3, why: 'The code is a floor.' },
      { q: 'When interpreting the code or facing a dilemma, a technician should:', opts: ['Decide alone.', 'Seek support from the supervisor and others in the workplace.', 'Ask the family to decide.', 'Search social media.'], a: 1, why: 'The code requires it, because the supervisor is responsible for the technician’s work.' },
      { q: 'In a dilemma, the code says to prioritize:', opts: ['Following the law and the client’s interests.', 'The employer’s income.', 'Your own convenience.', 'Avoiding paperwork.'], a: 0, why: 'Law first, and the client’s interests.' },
      { q: 'You suspect a colleague of an ethics violation. The first step is to:', opts: ['Report to the BACB immediately in every case.', 'Ignore it.', 'Bring it to your supervisor and document it.', 'Tell the family.'], a: 2, why: 'Supervisor first; the BACB if it is a code violation that is not resolved.' },
      { q: 'Documentation of an ethics concern includes:', opts: ['Your opinion of the person.', 'Nothing in writing.', 'Only the outcome.', 'The actions taken, dates, the parties involved and the outcome.'], a: 3, why: 'As the code describes.' },
      { q: 'The section of the code on self-reporting and honesty with the BACB is:', opts: ['Section 1.', 'Section 3.', 'Section 2.', 'The introduction.'], a: 1, why: 'Responsibilities to the BACB and the supervisor.' },
      { q: 'A risk of harm to a client is dealt with:', opts: ['At once, to protect the client, and then reported.', 'At the next supervision meeting.', 'After consulting colleagues informally.', 'Only if the family complains.'], a: 0, why: 'Protection comes first.' },
      { q: 'Who is responsible for all the work a technician performs?', opts: ['The technician alone.', 'The family.', 'The supervisor, under whose close direction the technician practices.', 'The BACB.'], a: 2, why: 'This is why questions and dilemmas go to the supervisor.' }
    ] },
    role: [
      { t: 'Bring a concern to your supervisor', setup: 'The trainer gives a written scenario in which a colleague may have broken a standard, and plays the supervisor.',
        steps: ['States the facts observed, with dates, without judging character.', 'Says who is affected and why it matters.', 'Names the principle or the area of the code involved.', 'Asks what to do, and what to do meanwhile.',
                'Says what they will write down and where.'] },
      { t: 'A friend asks you to keep quiet', setup: 'The trainer plays a colleague and friend who asks the trainee not to report a mistake that affected a student.',
        steps: ['Listens and acknowledges the colleague’s difficulty.', 'Says clearly that it has to be raised.', 'Does not promise secrecy.', 'Offers to go with the colleague to the supervisor, or says when they themselves will tell.'] }
    ],
    roleRule: 'Met when each role-play is done once with every step in place.',
    discuss: [
      'Read the RBT Ethics Code together, in full. Which standard surprised you?',
      'Which of the four principles is hardest to keep on a difficult day, and why?',
      'Who is “next” in your workplace if a concern is about your supervisor?'
    ],
    read: [
      'Behavior Analyst Certification Board. (2021). RBT Ethics Code (2.0). bacb.com. Read all of it.',
      'Behavior Analyst Certification Board. (2020). Ethics Code for Behavior Analysts, introduction (the core principles). bacb.com.',
      'Bailey, J. S., & Burch, M. R. (2022). Ethics for behavior analysts (4th ed.). Routledge.'
    ]
  },

  g2: {
    aim: [
      'Describe the technician’s role: what it includes and what belongs to the supervisor.',
      'Work only within your training and checked competence, and say so when asked to go beyond it.',
      'State the BACB’s ongoing supervision requirements and work out whether a month meets them.',
      'Take an active part in your own supervision.'
    ],
    lesson: [
      { h: 'What a technician is',
        p: ['A Registered Behavior Technician is a paraprofessional who delivers behavior-analytic services under the direction and close, ongoing supervision of a qualified supervisor. The certification does not allow independent practice. There is no such thing as an RBT working alone, privately, on their own plans.',
            'This is not a slight on technicians. It is how the service is built: the person who designs the plan has graduate training and is responsible for the outcome, and the person who delivers it has close support. The code says technicians provide services only within a clearly defined role under that supervision.'],
        check: { q: 'A family offers to pay you privately to “do ABA” with their child at weekends, with no supervisor. You:',
          opts: ['Accept: you are certified.', 'Accept if the plan is simple.', 'Decline: a technician may not practice without supervision.', 'Accept, and ask a friend to look at your notes.'],
          a: 2, why: 'Services under the certification require a supervisor who is responsible for the work.' } },
      { h: 'Yours and not yours',
        p: ['Yours: carrying out skill-teaching and behavior-reduction plans as written; collecting and recording data; assisting with assessments as directed; preparing materials; writing session notes; telling your supervisor what you see and hear.',
            'Not yours: designing or changing a plan; choosing targets or procedures; conducting or interpreting an assessment on your own; explaining results or prognosis to families; recommending services, schools, diets or medication; training parents unless you have been specifically trained and directed to deliver a part of it.',
            'The line is sometimes blurred by other people’s expectations. A teacher who says “you’re the behavior person, what should we do?” is asking a supervisor’s question. The answer is, “I’ll ask my supervisor today.”'],
        key: ['Carry out plans', 'Collect data', 'Assist with assessments as directed', 'Report to the supervisor', 'Not: design, change, interpret, recommend'],
        check: { q: 'A parent asks, “Should we stop using time-out at home?” The technician’s answer is:',
          opts: ['“That’s a good question for my supervisor. I’ll pass it on today.”', '“Yes, time-out doesn’t work.”', '“No, keep going.”', '“Try it for half as long.”'],
          a: 0, why: 'A recommendation about procedures belongs to the supervisor.' } },
      { h: 'Competence before service',
        p: ['Before you serve anyone, your supervisor must have confirmed that you can do what is being asked. After that, the two of you keep it under review. A procedure you have read about but never practiced is not one you are competent in.',
            'The code names two cases in particular: unfamiliar interventions and unfamiliar client populations both need proper training first. And restrictive or punishment-based procedures are carried out only when they are in a written behavior-change plan and your supervisor has verified your competence in them.',
            'When you are asked to go beyond your training or your role, by anyone, you tell your supervisor (or another appropriate person at your workplace) immediately, and you write down that you did.'],
        check: { q: 'Your caseload has always been young children. You are assigned an adult with dementia, starting tomorrow, with no preparation. You:',
          opts: ['Start, and learn on the job.', 'Tell your supervisor now that this population is new to you and you need training first, and document it.', 'Refuse and go home.', 'Use the same procedures as with the children.'],
          a: 1, why: 'An unfamiliar population needs training first, and the concern goes to the supervisor at once, in writing.' } },
      { h: 'Saying who you are',
        p: ['Describe yourself accurately: “I’m a Registered Behavior Technician. I work under the supervision of” your supervisor, by name. Not “therapist”, “behavior specialist” or “analyst” unless that is a title your employer has properly given you, and never in a way that suggests you design the plans.',
            'The code forbids false, misleading or exaggerated statements about your qualifications or services. It also asks you to give employers and supervisors accurate, current credentials when asked. If your certification lapses or goes inactive, you stop using the title and stop practicing until it is restored.'],
        check: { q: 'A teacher introduces you to a parent as “our autism expert”. You:',
          opts: ['Enjoy it.', 'Say nothing, to avoid embarrassing her.', 'Gently correct it: “I’m a behavior technician; I work under” your supervisor’s name, “who designs the program.”', 'Add that you are nearly a behavior analyst.'],
          a: 2, why: 'A misleading impression of your qualifications is corrected, kindly and at once.' } },
      { h: 'The supervision you must receive',
        p: ['The BACB sets minimum ongoing supervision for every practicing technician. Each calendar month, at least 5% of the hours you spend delivering behavior-analytic services must be supervised. There must be at least two face-to-face contacts in real time each month, and in at least one of them your supervisor must observe you delivering services. At least one of the two must be individual; the other may be a small-group meeting.',
            'Supervision is carried out by a qualified RBT Supervisor, within a structure overseen by an RBT Requirements Coordinator; the BACB’s handbook says who qualifies. You must have a supervisor on record in your BACB account. Without one, the certification is inactive: no practice, no billing, no use of the title.',
            'These are minimums. A new technician, a new case or a difficult procedure calls for more, and a good supervisor gives it.'],
        key: ['At least 5% of service hours, each calendar month', 'At least 2 real-time, face-to-face contacts', 'Observation of you with a client in at least 1', 'At least 1 individual'],
        check: { q: 'In March you deliver 120 hours of service. What is the least supervision that meets the 5% requirement?',
          opts: ['2 hours', '5 hours', '6 hours', '12 hours'],
          a: 2, why: '5% of 120 is 6 hours.' } },
      { h: 'Your part in it',
        p: ['Supervision is something you take part in, not something that is done to you. Keep your own running total of service hours and supervised hours through the month, so that a shortfall is seen in week three and not on the last day. If it looks as though the month will fall short, say so early.',
            'Both you and your supervisor keep records of supervision; the BACB requires them to be kept for seven years and may audit them. The workstation’s RBT Supervision Log is one place to keep them.',
            'Come prepared: bring your questions, the data you are unsure of, the step you find hard. Ask to be watched on the thing you do least well. Supervision that only confirms what you already do well wastes its purpose.'],
        check: { q: 'On the 20th you see that you have had 2 hours of supervision against 80 hours of service so far, and expect about 120 for the month. You:',
          opts: ['Wait: the supervisor keeps track.', 'Tell your supervisor now that about 4 more hours are needed before the month ends.', 'Reduce your service hours by calling in sick.', 'Record some planning time as supervision.'],
          a: 1, why: 'You track your own hours and speak early. A false entry is a breach of honesty with the BACB.' } },
      { h: 'What supervision is for',
        p: ['Good supervision includes watching you work, telling you precisely what you did well and what to change, showing you how, having you practice, and checking again. It also covers the cases: looking at the data together and explaining why a procedure is built as it is.',
            'The Staff Training and Competency form in the workstation follows the same order: instruction, modeling, rehearsal, feedback, and a check against a criterion. It is the method with the best evidence for teaching staff a procedure.'],
        check: { q: 'Which is the most useful request to bring to supervision?',
          opts: ['“Everything is fine.”', '“Can you watch me run the error correction? I think I am prompting too late.”', '“Can we finish early?”', '“Can you sign my form?”'],
          a: 1, why: 'It directs the supervisor’s observation to the place where you need feedback.' } }
    ],
    examples: {
      ask: 'Is this within the technician’s role?',
      intro: 'Ten things a technician might be asked to do. Decide whether each is within the role, or goes to the supervisor.',
      opts: ['Within the role', 'Outside the role: it goes to the supervisor'],
      items: [
        { s: 'Running the matching program as written and recording each trial.', a: 0, why: 'Carrying out a plan and collecting data.' },
        { s: 'Deciding that a program is mastered and replacing it with a new target.', a: 1, why: 'Changing targets is a design decision.' },
        { s: 'Running a preference assessment that your supervisor has trained you on and asked for.', a: 0, why: 'Assisting with an assessment, as directed.' },
        { s: 'Telling a parent what the assessment results mean for the child’s future.', a: 1, why: 'Interpreting results belongs to the supervisor.' },
        { s: 'Graphing today’s data on the student’s graph.', a: 0, why: 'Part of data collection and display.' },
        { s: 'Adding a response-cost step to the token system because the student is “getting away with it”.', a: 1, why: 'A change to the plan, and a punishment procedure outside it.' },
        { s: 'Telling your supervisor that the student has started to gag at snack.', a: 0, why: 'Reporting what you observe.' },
        { s: 'Advising a teacher on how to handle a different student who is not on your caseload.', a: 1, why: 'A recommendation, and about a student you do not serve.' },
        { s: 'Preparing the materials for tomorrow’s programs.', a: 0, why: 'Session preparation.' },
        { s: 'Writing the goals for the student’s next plan.', a: 1, why: 'Goal selection is the supervisor’s work.' }
      ]
    },
    practice: {
      title: 'Does this month meet the requirement?',
      intro: 'Work through one technician’s month. Zeno is a simulated technician.',
      ask: 'What is the answer?',
      steps: [
        { t: 'Service hours', see: 'In October Zeno delivered 22, 25, 24 and 29 hours of service in four weeks.', ask: 'How many service hours in the month?', opts: ['90', '100', '110'], a: 1, why: '22 + 25 + 24 + 29 = 100.' },
        { t: 'The 5%', see: '100 hours of service in the month.', ask: 'What is the least supervision required?', opts: ['2 hours', '5 hours', '10 hours'], a: 1, why: '5% of 100 is 5 hours.' },
        { t: 'What he had', see: 'Zeno’s log shows: Oct 6, 1.5 h, individual, supervisor observed him with a student. Oct 15, 1 h, group meeting with 4 other technicians. Oct 27, 1.5 h, individual, case review without a client.', ask: 'How many supervised hours?', opts: ['3', '4', '5'], a: 1, why: '1.5 + 1 + 1.5 = 4 hours.' },
        { t: 'Enough hours?', see: '4 hours of supervision against 100 hours of service.', ask: 'Is the 5% met?', opts: ['Yes', 'No: 1 hour short', 'No: 2 hours short'], a: 1, why: '4% was supervised. One more hour was needed.' },
        { t: 'Contacts', see: 'The same three entries.', ask: 'Are there at least two real-time, face-to-face contacts?', opts: ['Yes: three', 'No: one', 'No: none'], a: 0, why: 'All three were real-time contacts.' },
        { t: 'Observation', see: 'The same three entries.', ask: 'Was he observed delivering services in at least one?', opts: ['No', 'Yes: Oct 6', 'Yes: Oct 15'], a: 1, why: 'On Oct 6 the supervisor watched him with a student.' },
        { t: 'Individual', see: 'The same three entries.', ask: 'Was at least one contact individual?', opts: ['Yes: Oct 6 and Oct 27', 'No', 'Only the group meeting'], a: 0, why: 'Two were individual; one was a group.' },
        { t: 'What now', see: 'It is October 28. Zeno sees the one-hour shortfall.', ask: 'What does he do?', opts: ['Add an hour to the Oct 27 entry.', 'Tell his supervisor today, so that an hour can be arranged before the month ends.', 'Leave it: 4% is close.'], a: 1, why: 'There are still days left. An altered entry would be a false record.' }
      ]
    },
    quiz: { pass: 80, draw: 10, items: [
      { q: 'An RBT may practice:', opts: ['Independently, after one year.', 'Only under the close, ongoing supervision of a qualified supervisor.', 'Independently with simple cases.', 'Under the supervision of any senior colleague.'], a: 1, why: 'The certification has no independent practice.' },
      { q: 'Which is part of the technician’s role?', opts: ['Collecting data as the plan sets out.', 'Writing behavior plans.', 'Interpreting assessments for families.', 'Choosing new goals.'], a: 0, why: 'Implementation and data.' },
      { q: 'A technician asked to change a procedure by a teacher should:', opts: ['Change it.', 'Refuse rudely.', 'Take the request to the supervisor.', 'Change it for that classroom only.'], a: 2, why: 'Changes are the supervisor’s decision.' },
      { q: 'Before a technician provides services, the supervisor must have:', opts: ['Met the family.', 'Signed the timesheet.', 'Written a reference.', 'Confirmed that the technician has demonstrated competence.'], a: 3, why: 'Competence before service.' },
      { q: 'Asked to do something beyond your competence, you:', opts: ['Try anyway.', 'Inform your supervisor immediately and document it.', 'Quietly avoid the task.', 'Ask a colleague to do it and say nothing.'], a: 1, why: 'The code’s words: immediately inform, and document.' },
      { q: 'Restrictive or punishment-based procedures may be implemented by a technician:', opts: ['Only when in a documented plan and after the supervisor has verified competence.', 'Whenever behavior is severe.', 'When a parent asks.', 'Never, in any case.'], a: 0, why: 'Both conditions are required.' },
      { q: 'The least supervision each month is:', opts: ['1 hour.', '2% of service hours.', '5% of the hours spent delivering services.', '10 hours.'], a: 2, why: 'Five percent, counted each calendar month.' },
      { q: 'A technician delivers 60 hours of service in a month. The least supervision is:', opts: ['1 hour', '2 hours', '5 hours', '3 hours'], a: 3, why: '5% of 60 is 3.' },
      { q: 'Each month there must be at least:', opts: ['One phone call.', 'Two real-time, face-to-face contacts, with observation of service delivery in at least one.', 'One email.', 'Four group meetings.'], a: 1, why: 'Two contacts; one with observation.' },
      { q: 'Of the two monthly contacts:', opts: ['At least one must be individual.', 'Both must be group.', 'Neither needs to be live.', 'Both must be by message.'], a: 0, why: 'One individual; the other may be a small group.' },
      { q: 'With no supervisor on record, an RBT:', opts: ['May practice for 90 days.', 'May practice but not bill.', 'May not practice, bill or use the title.', 'Is unaffected.'], a: 2, why: 'The certification is inactive.' },
      { q: 'Supervision records are kept by:', opts: ['The supervisor only.', 'Nobody.', 'The family.', 'Both the technician and the supervisor, for seven years.'], a: 3, why: 'Both keep them, and the BACB may audit.' },
      { q: 'Describing yourself as a “behavior analyst” when you are an RBT is:', opts: ['Harmless.', 'A misleading statement about qualifications, which the code forbids.', 'Allowed with families you know well.', 'Allowed online.'], a: 1, why: 'Standard 1.05.' },
      { q: 'The best use of supervision time is:', opts: ['Being observed, getting specific feedback and practicing.', 'Having forms signed.', 'Chatting.', 'Hearing only praise.'], a: 0, why: 'Observation, feedback, modeling and rehearsal.' },
      { q: 'Who should notice a shortfall in the month’s supervision?', opts: ['Only the supervisor.', 'Only the BACB.', 'The technician too, by tracking their own hours.', 'The family.'], a: 2, why: 'Both are responsible for meeting and documenting it.' }
    ] },
    role: [
      { t: '“You’re the behavior person”', setup: 'The trainer plays, in turn, a teacher who wants advice about the plan and a parent who wants the assessment explained.',
        steps: ['States their role accurately, naming the supervisor.', 'Gives no recommendation or interpretation.', 'Says the question will go to the supervisor today.', 'Stays warm and helpful while declining.'] },
      { t: 'Beyond my training', setup: 'The trainer plays a manager who assigns the trainee a procedure they have not been trained on, starting now.',
        steps: ['Says plainly that they have not been trained or checked on it.', 'Asks for training before doing it.', 'Says they will inform their supervisor at once.', 'Says what they will write down.'] }
    ],
    roleRule: 'Met when each role-play is done once with every step in place.',
    discuss: [
      'Where is the edge of your role most often tested in your setting, and by whom?',
      'Work out last month’s supervision for yourself: service hours, 5%, contacts, observation.',
      'What would you most like to be observed doing?'
    ],
    read: [
      'Behavior Analyst Certification Board. RBT Handbook, ongoing supervision requirements. bacb.com.',
      'Behavior Analyst Certification Board. RBT Ethics Code (2.0). Standards 1.03 to 1.06, 2.04, 2.05 and 3.01. bacb.com.',
      'Parsons, M. B., Rollyson, J. H., & Reid, D. H. (2012). Evidence-based staff training: A guide for practitioners. Behavior Analysis in Practice, 5(2), 2–11.'
    ]
  },

  g3: {
    aim: [
      'Say what a multiple relationship is and why it puts the student at risk.',
      'Recognize the small steps by which professional boundaries slide.',
      'State the code’s rules on gifts and on romantic relationships.',
      'Decline warmly, and tell your supervisor at once when a multiple relationship exists or develops.'
    ],
    lesson: [
      { h: 'Two relationships at once',
        p: ['A multiple relationship is a mixing of roles: you are someone’s technician and also their friend, relative, babysitter, customer, tenant, business partner or employer. The code asks you to avoid them, with clients and their families, with coworkers and with supervisors.',
            'The reason is not that friendliness is wrong. It is that a second relationship gives you a second interest. A technician who babysits for the family at weekends may hesitate to report a concern that would lose her the work. A technician who is the mother’s close friend may shade the data, share too much, or be unable to say no. The student is the one who pays.'],
        check: { q: 'Why does the code ask technicians to avoid multiple relationships?',
          opts: ['Because families cannot be trusted.', 'Because technicians should be cold.', 'Because a second role can create a conflict of interest and a risk of harm to the client.', 'Because of insurance.'],
          a: 2, why: 'A conflict of interest can bend professional judgment.' } },
      { h: 'How boundaries slide',
        p: ['Hardly anyone decides to enter a multiple relationship. It arrives by steps, each of which seems kind: a ride home; a personal phone number; a friend request; staying for dinner; “could you just watch him for an hour on Saturday”; a loan; buying from the family’s business; a birthday party. In home-based work, where you are in someone’s kitchen ten hours a week, the pull is strong.',
            'The warning signs are in yourself: you are doing something for this family that you would not do for the others; you would rather your supervisor did not know; you are sharing your own troubles; you are thinking about the family’s feelings toward you during sessions.'],
        check: { q: 'Which is a warning sign that a boundary is sliding?',
          opts: ['You greet the family warmly.', 'You would prefer your supervisor not to know about it.', 'You arrive on time.', 'You follow the plan.'],
          a: 1, why: 'Secrecy from the supervisor is the clearest signal.' } },
      { h: 'When one exists or develops',
        p: ['Sometimes a second relationship is there from the start, especially in small communities: the new student is your neighbor’s son, or your cousin’s classmate’s brother. Sometimes it develops in spite of care.',
            'The code’s rule is the same either way: tell your supervisor immediately, work to resolve it, and document what was done. Resolving may mean a change of assignment, or clear agreed limits. It is your supervisor’s decision, not one to manage quietly yourself.',
            'If the multiple relationship involves your supervisor, the code sends you to your supervisor’s manager or another appropriate body, such as human resources or the BACB, again with a record.'],
        check: { q: 'You are assigned a new student and realize his mother is in your weekly choir. You:',
          opts: ['Say nothing: it is a big choir.', 'Leave the choir without telling anyone.', 'Tell the mother to keep it secret.', 'Tell your supervisor before the first session.'],
          a: 3, why: 'An existing relationship is disclosed at once, and the supervisor decides how it is handled.' } },
      { h: 'Gifts',
        p: ['Gifts create obligation, which is how they lead to conflicts of interest. The code’s rule: do not give to, or accept from, clients, their families and other stakeholders, or supervisors any gift worth more than 10 US dollars (or its equivalent). A small gift is acceptable as an occasional expression of thanks that brings no financial benefit. Small gifts that keep coming can still break the standard if they become a regular, expected source of value.',
            'If your employer’s policy is stricter, for example no gifts at all, that policy applies. Know which it is before the holidays arrive.',
            'In many cultures, refusing food or a gift is an insult, and families give out of real gratitude. Decline in a way that honors that: thank them warmly, name the rule as yours and not a judgment of them, and suggest something that is always welcome, such as a card or a drawing from the student. Then tell your supervisor, who can also help with what your workplace allows in a family’s home, such as a glass of water or a shared snack.'],
        check: { q: 'At the end of term a mother hands you an envelope with a 50-dollar gift card. You:',
          opts: ['Accept: refusing would be rude.', 'Accept and give it to charity.', 'Thank her sincerely, explain that you are not allowed to accept it, and tell your supervisor.', 'Accept and tell nobody.'],
          a: 2, why: 'It is well over the limit. A warm refusal, with the rule named, and a word to the supervisor.' } },
      { h: 'Romantic and sexual relationships',
        p: ['With current clients, their parents or other stakeholders, and your current supervisors: never. With former clients or stakeholders: not for at least two years after the professional relationship ended. With a former supervisor: not until it can be documented that the professional relationship has ended. And you do not receive supervision from someone with whom you have had a romantic or sexual relationship until at least six months after it ended.',
            'The power in these relationships is unequal, and consent given inside them cannot be relied upon. If you find an attraction developing, on either side, that is a matter to bring to your supervisor (or, if it concerns your supervisor, to the next person), early, before anything has happened.'],
        check: { q: 'A student’s single father asks you out to dinner. His son is on your caseload. You:',
          opts: ['Accept, if you keep it quiet.', 'Decline clearly and kindly, and tell your supervisor.', 'Accept after the school year ends in June.', 'Say “maybe later”.'],
          a: 1, why: 'A parent is a stakeholder: never while services continue, and not for two years after. “Maybe later” leaves it open; the supervisor needs to know.' } },
      { h: 'Social media, phones and favors',
        p: ['Do not connect with clients’ families on personal social media. Keep work communication on the channel your workplace provides, about work, in working hours. If a family finds your personal account or number, tell your supervisor.',
            'Do not babysit, tutor privately, give lifts, lend or borrow money, buy from or sell to families, or hire them. Do not ask families for favors. When a parent begins to confide personal troubles at length, listen briefly and kindly, and suggest who could help; you are not their counselor or friend.',
            'None of this makes you cold. Warmth, reliability and interest in the child are the professional relationship. Boundaries are what let the family trust that your judgment is not for sale.'],
        check: { q: 'A mother you like very much sends you a friend request on your personal account. You:',
          opts: ['Accept, but hide your posts.', 'Leave it unanswered, mention kindly at the next session that you don’t connect with families online, and tell your supervisor.', 'Accept: it would be awkward not to.', 'Block her without a word.'],
          a: 1, why: 'The boundary is kept, explained as a rule that applies to everyone, and the supervisor is told.' } }
    ],
    examples: {
      ask: 'Is this within the code?',
      intro: 'Eight situations. Decide whether each is acceptable under the code (your employer’s policy may be stricter), or not.',
      opts: ['Acceptable under the code', 'Not acceptable, or needs your supervisor at once'],
      items: [
        { s: 'A student gives you a drawing he made for you.', a: 0, why: 'A token of thanks with no monetary value.' },
        { s: 'A family gives you a 40-dollar scented candle set at the holidays.', a: 1, why: 'Over the limit.' },
        { s: 'A parent brings you a coffee, worth about 4 dollars, every single session.', a: 1, why: 'Each is small, but ongoing gifts can become a regular, expected source of value. Raise it with your supervisor.' },
        { s: 'On your last day, a family gives you a thank-you card and a chocolate bar.', a: 0, why: 'An occasional expression of gratitude under the limit.' },
        { s: 'You agree to babysit your student on Saturday nights for pay.', a: 1, why: 'A second, paid role with the family.' },
        { s: 'You discover that your new student’s father is your landlord, and you tell your supervisor the same day.', a: 0, why: 'An existing relationship, disclosed immediately so that it can be resolved. This is what the code asks.' },
        { s: 'You give your student a 25-dollar toy for his birthday.', a: 1, why: 'The limit applies to giving as well as receiving.' },
        { s: 'You begin dating a student’s older sister, who attends his planning meetings.', a: 1, why: 'A romantic relationship with a current stakeholder.' }
      ]
    },
    practice: {
      title: 'A year in one home',
      intro: 'You work in the home of Aldo, a simulated student, three afternoons a week. His family is kind and generous.',
      steps: [
        { t: 'Week 2', see: 'Aldo’s grandmother puts a full plate of dinner in front of you. Your workplace’s policy allows a drink and nothing more.', opts: ['Eat it: refusing is rude.', '“It smells wonderful, thank you. I’m not allowed to eat while I’m working, but I’d love a glass of water.”', '“No.”'], a: 1, why: 'The policy is kept, and her kindness is honored.' },
        { t: 'Week 6', see: 'Aldo’s mother says, “Give me your mobile number, it’s easier than the office line.”', opts: ['Give it.', 'Explain that messages go through the work channel so that your supervisor sees them too, and show her how.', 'Give it but ask her to use it rarely.'], a: 1, why: 'Work communication stays on the work channel.' },
        { t: 'Week 10', see: 'She asks, “Could you stay an extra hour on Friday and just watch him while I go to the shop? I’ll pay you cash.”', opts: ['Agree: it helps her.', 'Agree but refuse the money.', 'Decline kindly: you can only be there as his technician, in scheduled sessions. Tell your supervisor.'], a: 2, why: 'Babysitting, paid or not, is a second role.' },
        { t: 'Week 16', see: 'She begins to tell you, most days, about her marriage, and cries.', opts: ['Become her confidante: she has nobody.', 'Listen briefly and kindly, say you are sorry things are hard, and tell your supervisor, who can suggest support for her.', 'Tell her about your own relationship.'], a: 1, why: 'Compassion without becoming her counselor or friend. The supervisor can point her to real help.' },
        { t: 'Week 24', see: 'At the holidays the family gives you a wrapped box. Inside is a watch.', opts: ['Keep it: they would be hurt.', 'Thank them warmly, explain that you cannot accept gifts over a small value, return it, and tell your supervisor.', 'Keep it and give them something of equal value.'], a: 1, why: 'Far over the limit. An exchange of gifts doubles the problem.' },
        { t: 'Week 30', see: 'You are invited to Aldo’s birthday party on a Saturday.', opts: ['Go as a guest and stay all afternoon.', 'Ask your supervisor what your workplace’s policy is before answering.', 'Ignore the invitation.'], a: 1, why: 'Workplaces differ on this. It is a boundary question for the supervisor, not one to settle alone.' },
        { t: 'Week 40', see: 'Aldo’s uncle, who lives in the house and attends team meetings, asks you on a date.', opts: ['Accept: he is not the parent.', 'Decline clearly and kindly, and tell your supervisor.', 'Say you will think about it.'], a: 1, why: 'He is a stakeholder. The answer is no, and the supervisor is told.' }
      ]
    },
    quiz: { pass: 80, draw: 10, items: [
      { q: 'A multiple relationship is:', opts: ['Having several clients.', 'A mixing of two or more roles with a client, stakeholder, supervisor or coworker.', 'Working at two schools.', 'Having two supervisors.'], a: 1, why: 'For example, technician and friend, or technician and employee of the family.' },
      { q: 'The main risk of a multiple relationship is:', opts: ['A conflict of interest that can harm the client.', 'Extra paperwork.', 'Longer days.', 'Jealous colleagues.'], a: 0, why: 'Judgment bent by a second interest.' },
      { q: 'If you find that a multiple relationship has developed, you:', opts: ['Manage it discreetly.', 'End services yourself.', 'Wait to see whether it causes trouble.', 'Immediately tell your supervisor, work to resolve it, and document it.'], a: 3, why: 'The code’s three steps.' },
      { q: 'If the multiple relationship involves your supervisor, you report it to:', opts: ['Nobody.', 'The client’s family.', 'Your supervisor’s manager or another appropriate body, and document it.', 'Your friends.'], a: 2, why: 'The code names the manager, human resources or the BACB.' },
      { q: 'The code’s limit on the value of a gift given or accepted is:', opts: ['10 US dollars.', '25 US dollars.', '50 US dollars.', 'No limit, if it is sincere.'], a: 0, why: 'Standard 1.11.' },
      { q: 'The gift rule covers gifts between the technician and:', opts: ['Clients only.', 'Clients, stakeholders and supervisors.', 'Coworkers only.', 'Strangers.'], a: 1, why: 'In both directions.' },
      { q: 'An acceptable small gift is:', opts: ['A weekly payment in kind.', 'Anything under 100 dollars.', 'Anything given in private.', 'An occasional expression of gratitude that brings no financial benefit.'], a: 3, why: 'Occasional, small, and not a source of income or value.' },
      { q: 'Your employer forbids all gifts. A parent offers a 5-dollar gift. You:', opts: ['Accept: the code allows it.', 'Accept and report it.', 'Decline kindly: the stricter policy applies.', 'Accept half.'], a: 2, why: 'A stricter employer policy is followed.' },
      { q: 'Romantic relationships with current clients, stakeholders or supervisors are:', opts: ['Allowed if disclosed.', 'Never allowed.', 'Allowed with consent.', 'Allowed off site.'], a: 1, why: 'Standard 1.12.' },
      { q: 'After the professional relationship ends, a romantic relationship with a former client or stakeholder is not allowed for at least:', opts: ['Two years.', 'Six months.', 'One year.', 'Thirty days.'], a: 0, why: 'A minimum of two years.' },
      { q: 'You may not receive supervision from a former romantic partner until at least:', opts: ['Two years after it ended.', 'One month after it ended.', 'Six months after it ended.', 'Never.'], a: 2, why: 'At least six months.' },
      { q: 'A family asks you to babysit at the weekend. This is:', opts: ['A kindness you should do.', 'Fine if unpaid.', 'Fine if the supervisor is not told.', 'A second role to decline, and to mention to your supervisor.'], a: 3, why: 'It creates a multiple relationship.' },
      { q: 'A parent sends a friend request to your personal account. You:', opts: ['Accept.', 'Do not accept, explain your rule kindly, and tell your supervisor.', 'Accept and mute them.', 'Report them to the BACB.'], a: 1, why: 'Personal social media is kept apart from families.' },
      { q: 'The best way to refuse a gift is to:', opts: ['Thank the giver warmly and name the rule as one you must follow.', 'Refuse without explanation.', 'Lecture the family about ethics.', 'Accept, then return it by post.'], a: 0, why: 'The relationship is protected along with the boundary.' }
    ] },
    role: [
      { t: 'The gift', setup: 'The trainer plays a grateful parent who presses an expensive gift on the trainee and is a little hurt at the refusal.',
        steps: ['Thanks the parent sincerely.', 'Declines clearly.', 'Names the rule as their own obligation, not a judgment of the family.', 'Suggests something that is welcome (a card, a drawing).', 'Says they will mention it to their supervisor.'] },
      { t: 'The favor', setup: 'The trainer plays a parent who asks for the trainee’s personal number, then for babysitting, then invites them to a family event.',
        steps: ['Keeps communication on the work channel, with a reason.', 'Declines the babysitting kindly and without leaving it open.', 'Does not accept or refuse the invitation before asking the supervisor.', 'Stays warm throughout.'] }
    ],
    roleRule: 'Met when each role-play is done once with every step in place.',
    discuss: [
      'What is your workplace’s policy on gifts, food in homes, and invitations? Where is it written?',
      'Which boundary would be hardest for you to hold, and with what kind of family?',
      'In a small community, which second relationships can you not avoid? How are they handled?'
    ],
    read: [
      'Behavior Analyst Certification Board. RBT Ethics Code (2.0). Standards 1.10, 1.11 and 1.12, and the glossary entries “multiple relationship” and “conflict of interest”. bacb.com.',
      'Witts, B. N., Brodhead, M. T., Adlington, L. C., & Barron, D. K. (2020). Behavior analysts accept gifts during practice: So now what? Behavior Analysis: Research and Practice, 20(3), 196–202.'
    ]
  }
});
